Interview task: write a `@log` method decorator using TypeScript 5 standard decorators (no `experimentalDecorators`). It should log the method name and then call the original method with the same `this` and arguments. It is used like this:

```ts
class Cart {
  items = [1, 2];
  @log count() { return this.items.length; }
}
```

Which implementation compiles under `strict` and works?

options.text:
```ts
function log(target: Function, ctx: ClassMethodDecoratorContext) {
  return (...args: unknown[]) => {
    console.log(`calling ${String(ctx.name)}`);
    return target.apply(this, args);
  };
}
```

```ts
function log(target: (...args: any[]) => any, ctx: ClassMethodDecoratorContext) {
  return function (...args: any[]) {
    console.log(`calling ${String(ctx.name)}`);
    return target(...args);
  };
}
```

```ts
function log(target: any, key: string, descriptor: PropertyDescriptor) {
  const original = descriptor.value;
  descriptor.value = function (...args: any[]) {
    console.log(`calling ${key}`);
    return original.apply(this, args);
  };
}
```

```ts
function log<This, Args extends unknown[], R>(
  target: (this: This, ...args: Args) => R,
  ctx: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => R>
) {
  return function (this: This, ...args: Args): R {
    console.log(`calling ${String(ctx.name)}`);
    return target.call(this, ...args);
  };
}
```

