A candidate's typed `Promise.all` polyfill passes simple tests. What does it log for these inputs?

```ts
function myAll<T>(values: readonly (T | PromiseLike<T>)[]): Promise<T[]> {
  return new Promise((resolve, reject) => {
    const results: T[] = [];
    values.forEach((v, i) => {
      Promise.resolve(v).then((val) => {
        results[i] = val;
        if (results.length === values.length) resolve(results);
      }, reject);
    });
  });
}

const delay = <V>(ms: number, v: V) => new Promise<V>((r) => setTimeout(() => r(v), ms));
myAll([delay(30, "a"), delay(10, "b"), delay(20, "c")]).then(console.log);
```

